import{_ as t,o as e,c as n,aO as i}from"./chunks/framework.vjUPZZJn.js";const u=JSON.parse('{"title":"CycloneDDS 多参与者合并：SquashParticipants 配置","description":"","frontmatter":{"date":"2026-09-24T21:30:00.000Z","title":"CycloneDDS 多参与者合并：SquashParticipants 配置","source":[["1-知识/中间件/DDS/CycloneDDS 合并多个参与者"]],"tags":["中间件","学习笔记","DDS","CycloneDDS"],"categories":["机器人"],"permalink":"/pages/20e809"},"headers":[],"relativePath":"机器人/CycloneDDS 多参与者合并：SquashParticipants 配置.md","filePath":"机器人/CycloneDDS 多参与者合并：SquashParticipants 配置.md","lastUpdated":1790247621000}'),l={name:"机器人/CycloneDDS 多参与者合并：SquashParticipants 配置.md"};function r(o,a,s,c,p,d){return e(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="cyclonedds-多参与者合并-squashparticipants-配置" tabindex="-1">CycloneDDS 多参与者合并：SquashParticipants 配置 <a class="header-anchor" href="#cyclonedds-多参与者合并-squashparticipants-配置" aria-label="Permalink to &quot;CycloneDDS 多参与者合并：SquashParticipants 配置&quot;">​</a></h1> <p>单个进程创建多个 DCPS 参与者时，每个参与者都会在 DDSI 层独立参与发现与活跃性声明，后台消息量随之成倍上涨——单进程在网络上看起来像一个拥有大量参与者的大系统。CycloneDDS 提供了两个配置项来合并进程内的多个参与者，本文整理自官方文档 <a href="https://cyclonedds.io/docs/cyclonedds/latest/config/combining-participants.html" target="_blank" rel="noreferrer">Combining multiple participants</a>（11.0.0），适合遇到发现流量过大或想优化多参与者进程的读者。</p> <h2 id="问题-进程内多参与者的后台流量" tabindex="-1">问题：进程内多参与者的后台流量 <a class="header-anchor" href="#问题-进程内多参与者的后台流量" aria-label="Permalink to &quot;问题：进程内多参与者的后台流量&quot;">​</a></h2> <p>上层框架在单个进程里创建多个参与者并不少见。每个参与者都要发送自己的活跃性断言（liveliness assertion）并维护各自的发现端点，参与者的数量直接决定这些周期性后台消息的规模。当进程内参与者很多时，这部分开销会变得可观。</p> <h2 id="internal-squashparticipants" tabindex="-1">Internal/SquashParticipants <a class="header-anchor" href="#internal-squashparticipants" aria-label="Permalink to &quot;Internal/SquashParticipants&quot;">​</a></h2> <p>把这个内部选项设为 <code>true</code>，可以把进程内的多个 DCPS 域参与者合并为单个 DDSI 域参与者对外呈现——对外相当于只存在一个参与者，它拥有该进程创建的所有端点。</p> <p>收益是后台消息量显著减少：活跃性断言只需要按一个参与者发送，而不是每个参与者各发一份。</p> <p>代价同样明确：</p> <ul><li>工具无法再显示真实的系统拓扑结构——所有端点都挂在同一个参与者名下</li> <li>与域参与者相关的活跃性监控会受影响；对 <code>AUTOMATIC_LIVELINESS</code>（默认的自动活跃性）没有问题，手动活跃性相关的监控语义会失真</li></ul> <p>还有一个容易踩的细节：<strong>保留下来的唯一参与者，其 QoS 属性取自进程中创建的第一个参与者</strong>。如果其他参与者设置了各自的用户数据（UserData），这些数据在远程节点上均不可见。</p> <h2 id="替代方案-internal-builtinendpointset-minimal" tabindex="-1">替代方案：Internal/BuiltinEndpointSet = minimal <a class="header-anchor" href="#替代方案-internal-builtinendpointset-minimal" aria-label="Permalink to &quot;替代方案：Internal/BuiltinEndpointSet = minimal&quot;">​</a></h2> <p>如果不想合并参与者，可以把 <code>Internal/BuiltinEndpointSet</code> 设为 <code>minimal</code>：此时只有第一个参与者拥有内置端点的 Writer，并在所有实体上发布数据，同样能减少一部分内置通道的流量。</p> <p>注意此设置与其他 DDS 实现并非完全兼容：它意味着本方可能会收到尚未被发现的参与者的端点发现数据。跨厂商互操作的场景要谨慎评估。</p> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>进程内多参与者 → 活跃性断言等后台消息成倍增长；<code>Internal/SquashParticipants=true</code> 合并呈现为一个参与者，代价是拓扑工具失真、参与者级活跃性监控受影响（自动活跃性除外）</li> <li>合并后保留参与者的 QoS 取自<strong>第一个</strong>创建的参与者，其余参与者的 UserData 对远端不可见</li> <li>不合并的替代项是 <code>Internal/BuiltinEndpointSet=minimal</code>，但有跨实现兼容性风险</li> <li>两者都是 <code>Internal/</code> 前缀的内部选项，升级 CycloneDDS 版本时值得复查行为是否变化</li></ul>',29)])])}const S=t(l,[["render",r]]);export{u as __pageData,S as default};
